def herb_card(i):
    n, sci, use, prep, flav, grow, care = HERBS[i]
    return C(n, sci, [use], [(('Preparo', 'Brew'), prep), (('Sabor', 'Flavour'), flav), (('Cultivo', 'Growing'), grow), (('Cuidado', 'Caution'), care)])


def herbs_page(a, b):
    return text(None, body=grid(2, *[herb_card(i) for i in range(a, min(b, len(HERBS)))]), chapter=('Catorze ervas', 'Fourteen herbs'))


